function validate([root]) {
  if (!root.length || root[0] === null) return 'The tree needs at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 1000) return 'The tree has at most 1000 nodes.';
  if (values.some(v => v !== 0)) return 'Every node value is 0.';
  return null;
}

