function minCameraCover(root) {
  // For a subtree, solve returns the fewest cameras in three situations:
  // open: everything below node is watched, node itself is not;
  // covered: everything is watched and node has no camera;
  // camera: everything is watched and node has a camera.
  function solve(node) {
    if (node === null) return [0, 0, Infinity];
    const [leftOpen, leftCovered, leftCamera] = solve(node.left);
    const [rightOpen, rightCovered, rightCamera] = solve(node.right);

    const open = leftCovered + rightCovered;
    const viaLeft = leftCamera + Math.min(rightCovered, rightCamera);
    const viaRight = rightCamera + Math.min(leftCovered, leftCamera);
    const covered = Math.min(viaLeft, viaRight);
    const leftBest = Math.min(leftOpen, leftCovered, leftCamera);
    const rightBest = Math.min(rightOpen, rightCovered, rightCamera);
    const camera = 1 + leftBest + rightBest;
    return [open, covered, camera];
  }

  const [, covered, camera] = solve(root);
  return Math.min(covered, camera);
}

