function minCameraCover(root) {
  // Try every set of camera nodes and keep the smallest one that watches the whole tree.
  const near = [];
  const stack = [[root, -1]];
  while (stack.length) {
    const [node, up] = stack.pop();
    const id = near.length;
    near.push([id]);
    if (up >= 0) { near[id].push(up); near[up].push(id); }
    if (node.left) stack.push([node.left, id]);
    if (node.right) stack.push([node.right, id]);
  }
  const n = near.length;
  let best = n;
  for (let mask = 0; mask < 2 ** n; mask++) {
    const watched = new Array(n).fill(false);
    let count = 0;
    for (let i = 0; i < n; i++) {
      if (Math.floor(mask / 2 ** i) % 2 === 0) continue;
      count++;
      for (const j of near[i]) watched[j] = true;
    }
    if (count < best && watched.every(Boolean)) best = count;
  }
  return best;
}

