function generate(rand, size) {
  const n = size === 'large' ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 12);
  // Attach each new node to a free child slot. A high bias keeps picking the newest slots,
  // which grows long chains; a low bias gives bushy trees.
  const bias = rand();
  const nodes = [{ left: null, right: null }], slots = [[0, 'left'], [0, 'right']];
  for (let i = 1; i < n; i++) {
    const k = rand() < bias ? slots.length - 1 - Math.floor(rand() * Math.min(2, slots.length)) : Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [], queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    out.push(0);
    queue.push(nodes[queue[q]].left, nodes[queue[q]].right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
